#!/usr/bin/env node
/**
 * dsh-skill-router — turn the DSH skill catalog into a router + on-demand indexes.
 *
 *   scan     show every root DSH scans, the resident catalog cost, and the skills
 *            DSH silently skips (invalid frontmatter). Read-only.
 *   plan     preview the classification, index sizes and link actions. Read-only.
 *   apply    link the source libraries into the off-root, write the router skill
 *            and the per-category indexes.
 *   verify   check that every path written into an index actually resolves.
 *   restore  roll back links and generated files. Source libraries are untouched.
 *   route    answer the other half: given one task sentence, which index should be
 *            read first. Pure function over a routing file; no disk discovery.
 *
 * Zero dependencies. Node >= 20 (the same floor DSH itself requires).
 */
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

import {
  discoverRoots, listSkills, findProjectRoot, readCustomSkillDirs,
} from '../src/roots.mjs';
import { measureCatalog, estimateTokens, DEFAULT_DESC_CAP } from '../src/catalog.mjs';
import { buildBuckets, indexEntryTokens } from '../src/classify.mjs';
import { link, unlink, IS_WINDOWS, linkType } from '../src/mount.mjs';
import {
  routerText, indexText, managerText, writeIfChanged, ROUTER_NAME, MANAGER_NAME,
} from '../src/generate.mjs';
import { verifyIndexes } from '../src/verify.mjs';
import {
  routeQuery, validateRouting, resolveHubPath, orderedRules,
} from '../src/route.mjs';

const VERSION = '1.1.0';
const MARKER = `generated by dsh-skill-router@${VERSION}`;

// ────────────────────────────── arg parsing ──────────────────────────────
function usage(code = 0) {
  const t = `
dsh-skill-router v${VERSION} — shrink the DSH skill catalog to one router skill.

USAGE
  dsh-skill-router <command> [options]

COMMANDS
  scan      Show every root DSH scans, the resident catalog cost, and skills DSH
            silently skips (bad frontmatter). Read-only.
  plan      Preview categories, index sizes and link actions. Read-only.
  apply     Link source libraries into the off-root; write router + indexes.
  verify    Fail (exit 1) if any index path no longer resolves.
  restore   Remove links and generated files. Source libraries are never touched.
  route     Given a task sentence, print the PRIMARY category index (and hub) to
            read first. Reads a routing file; writes nothing.

OPTIONS
  --source <dir>        A skill library whose immediate children are skill bundles
                        (<name>/SKILL.md or <name>.md). Repeatable.
                        For the route command: also searched when resolving hubs.
  --exclude <name>      Skip a skill by directory name; "prefix*" matches a family.
                        Repeatable.
  --exclude-file <f>    JSON array of names to exclude.
  --overrides <f>       JSON map { "<skill-dir-name>": "<category>" } applied first.
  --max-tokens <n>      Budget per index file (default 4000). Oversized categories
                        are split; undersized ones fold into "other".
  --locale <zh|en>      Router/index language (default en).
  --routing <f>         Routing file for route. Default: <dsh-home>/capabilities/routing.json.
  --hub-root <dir>      Extra root searched when resolving hub paths. Repeatable.
  --validate            route --validate: check the routing file only, then exit.
  --skills-root <dir>   Default: <dsh-home>/skills
  --off-dir <dir>       Default: <dsh-home>/skills-off
  --index-dir <dir>     Default: <dsh-home>/skill-index
  --dsh-home <dir>      Default: $DSH_HOME or ~/.dsh
  --profile <name>      Profile whose cordis.patch.yml is read for customSkillDirs
  --project-root <dir>  Default: nearest .git ancestor of cwd
  --dry-run             Apply without writing anything.
  --json                Machine-readable output (scan/plan/verify).
  -h | --help
`;
  process.stdout.write(t);
  process.exit(code);
}

function parseArgs(argv) {
  const o = {
    command: null, sources: [], excludes: [], excludeFile: null, overrides: null,
    maxTokens: 4000, locale: 'en', dryRun: false, json: false,
    skillsRoot: null, offDir: null, indexDir: null, dshHome: null,
    profile: 'desktop', projectRoot: null,
    routing: null, hubRoots: [], rest: [], validate: false,
  };
  const need = (v, flag) => { if (v == null) usage(1); };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!o.command && !a.startsWith('-')) { o.command = a; continue; }
    if (o.command === 'route' && !a.startsWith('-')) { o.rest.push(a); continue; }
    switch (a) {
      case '-h': case '--help': usage(0); break;
      case '--source': o.sources.push(path.resolve(argv[++i])); break;
      case '--exclude': o.excludes.push(argv[++i]); break;
      case '--exclude-file': o.excludeFile = path.resolve(argv[++i]); break;
      case '--overrides': o.overrides = path.resolve(argv[++i]); break;
      case '--max-tokens': o.maxTokens = Number(argv[++i]); break;
      case '--locale': o.locale = argv[++i]; break;
      case '--skills-root': o.skillsRoot = path.resolve(argv[++i]); break;
      case '--off-dir': o.offDir = path.resolve(argv[++i]); break;
      case '--index-dir': o.indexDir = path.resolve(argv[++i]); break;
      case '--dsh-home': o.dshHome = path.resolve(argv[++i]); break;
      case '--profile': o.profile = argv[++i]; break;
      case '--project-root': o.projectRoot = path.resolve(argv[++i]); break;
      case '--dry-run': o.dryRun = true; break;
      case '--json': o.json = true; break;
      case '--routing': o.routing = path.resolve(argv[++i]); break;
      case '--hub-root': o.hubRoots.push(path.resolve(argv[++i])); break;
      case '--validate': o.validate = true; break;
      default: process.stderr.write(`unknown option: ${a}\n`); usage(1);
    }
  }
  if (!['scan', 'plan', 'apply', 'verify', 'restore', 'route'].includes(o.command)) {
    process.stderr.write(`missing or unknown command\n`);
    usage(1);
  }
  return o;
}

// ────────────────────────────── helpers ──────────────────────────────
function loadJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function isExcluded(name, excludes) {
  return excludes.some((x) => (x.endsWith('*') ? name.startsWith(x.slice(0, -1)) : name === x));
}

/** Extract extra frontmatter fields the classifier needs. */
function extraFields(block) {
  const out = {};
  const sub = /^\s*subdomain\s*:\s*(.+?)\s*$/m.exec(block || '');
  if (sub) out.subdomain = sub[1].replace(/^['"]|['"]$/g, '').trim();
  const cat = /^\s*category\s*:\s*(.+?)\s*$/m.exec(block || '');
  if (cat) out.metadata = { category: cat[1].replace(/^['"]|['"]$/g, '').trim() };
  return out;
}

/**
 * Collect catalog-able skills from the user-supplied source libraries.
 * Mirrors DSH's one-level rule. Invalid skills are reported, not linked.
 */
function collectFromSources(sources, excludes) {
  const skills = [];
  const invalid = [];
  const seen = new Map(); // lower(name) -> first source
  for (const src of sources) {
    if (!fs.existsSync(src)) { process.stderr.write(`warning: source not found: ${src}\n`); continue; }
    let entries;
    try { entries = fs.readdirSync(src, { withFileTypes: true }); }
    catch { process.stderr.write(`warning: source unreadable: ${src}\n`); continue; }

    for (const e of entries) {
      let skillFile = null; let dirName = null; let kind = null;
      if (e.isDirectory() || e.isSymbolicLink()) {
        const p = path.join(src, e.name, 'SKILL.md');
        if (fs.existsSync(p)) { skillFile = p; dirName = e.name; kind = 'dir'; }
      }
      if (!skillFile && e.isFile() && /\.md$/i.test(e.name) && !/^skill\.md$/i.test(e.name)) {
        skillFile = path.join(src, e.name); dirName = e.name.replace(/\.md$/i, ''); kind = 'file';
      }
      if (!skillFile) continue;

      const parsed = parseSkill(skillFile, dirName);
      const key = parsed.name.toLowerCase();
      if (seen.has(key)) {
        invalid.push({ name: parsed.name, dir: src, reason: `duplicate of "${seen.get(key)}" (first wins)` });
        continue;
      }
      seen.set(key, src);
      if (!parsed.valid) { invalid.push({ name: parsed.name, dir: skillFile, reason: parsed.reason }); continue; }
      if (isExcluded(dirName, excludes) || isExcluded(parsed.name, excludes)) continue;

      skills.push({
        name: parsed.name, dirName, description: parsed.description || '',
        skillFile, kind, source: src, block: parsed.block, ...extraFields(parsed.block),
      });
    }
  }
  return { skills, invalid };
}

// re-export the tolerant frontmatter reader (BOM / comment-banner aware)
import { parseSkillName as parseSkill } from '../src/roots.mjs';

function resolveDirs(o) {
  const dshHome = o.dshHome ?? process.env.DSH_HOME ?? path.join(process.env.USERPROFILE || process.env.HOME, '.dsh');
  return {
    dshHome,
    skillsRoot: o.skillsRoot ?? path.join(dshHome, 'skills'),
    offDir: o.offDir ?? path.join(dshHome, 'skills-off'),
    indexDir: o.indexDir ?? path.join(dshHome, 'skill-index'),
  };
}

function fmtTokens(n) { return n.toLocaleString('en-US'); }

// ────────────────────────────── scan ──────────────────────────────
function cmdScan(o) {
  const dirs = resolveDirs(o);
  const roots = discoverRoots({
    dshHome: dirs.dshHome, profile: o.profile, projectRoot: o.projectRoot ?? undefined,
  });
  const seen = new Set();
  const rows = [];
  const invalidAll = [];
  let resident = [];
  for (const r of roots) {
    const found = listSkills(r, seen);
    const valid = found.filter((s) => s.valid && !s.shadowed);
    const bad = found.filter((s) => !s.valid);
    const shadowed = found.filter((s) => s.shadowed);
    resident.push(...valid);
    invalidAll.push(...bad.map((b) => ({ name: b.name, dir: b.skillFile, reason: b.reason })));
    rows.push({ rank: r.rank, source: r.source, dir: r.dir, exists: r.exists,
      skills: valid.length, invalid: bad.length, shadowed: shadowed.length });
  }
  const m = measureCatalog(resident);

  if (o.json) {
    process.stdout.write(JSON.stringify({ roots: rows, catalog: m, invalid: invalidAll }, null, 2) + '\n');
  } else {
    process.stdout.write(`DSH skill roots (rank = catalog priority; first root defining a name wins)\n\n`);
    for (const r of rows) {
      process.stdout.write(
        `  ${String(r.rank).padStart(3)}  ${r.source.padEnd(15)} ` +
        `${r.exists ? 'yes'.padEnd(5) : 'no   '} skills=${String(r.skills).padStart(4)}  ` +
        `invalid=${String(r.invalid).padStart(3)}  shadowed=${String(r.shadowed).padStart(3)}  ${r.dir}\n`
      );
    }
    process.stdout.write(`\nResident catalog (what DSH ships in every request)\n`);
    process.stdout.write(`  entries          : ${m.entries}\n`);
    process.stdout.write(`  chars (capped@${DEFAULT_DESC_CAP}) : ${m.chars.toLocaleString('en-US')}\n`);
    process.stdout.write(`  ~tokens          : ${fmtTokens(m.tokens)}\n`);
    if (m.cappedCount) process.stdout.write(`  capped descriptions: ${m.cappedCount}\n`);
    if (invalidAll.length) {
      process.stdout.write(`\nSkills DSH silently skips (${invalidAll.length}) — these cost a link but never appear:\n`);
      for (const b of invalidAll.slice(0, 30)) {
        process.stdout.write(`  ${b.name.padEnd(46)} ${b.reason.padEnd(18)} ${b.dir}\n`);
      }
      if (invalidAll.length > 30) process.stdout.write(`  … +${invalidAll.length - 30} more\n`);
      process.stdout.write(`\n  Fix: give each a minimal frontmatter block:\n`);
      process.stdout.write(`    ---\n    name: <skill-name>\n    description: <one line, when to use it>\n    ---\n`);
    }
  }
}

// ────────────────────────────── plan / apply ──────────────────────────────
function buildPlan(o) {
  const dirs = resolveDirs(o);
  if (!o.sources.length) {
    process.stderr.write(`error: at least one --source is required for ${o.command}\n`);
    process.exit(1);
  }
  let excludes = [...o.excludes];
  if (o.excludeFile) {
    const arr = loadJson(o.excludeFile);
    if (!Array.isArray(arr)) { process.stderr.write(`error: --exclude-file must be a JSON array\n`); process.exit(1); }
    excludes.push(...arr.map(String));
  }
  const overrides = o.overrides ? loadJson(o.overrides) : {};
  const { skills, invalid } = collectFromSources(o.sources, excludes);
  const buckets = buildBuckets(skills, { maxTokens: o.maxTokens, overrides });

  const linkActions = [];
  const seenDirs = new Set();
  for (const s of skills) {
    if (seenDirs.has(s.dirName)) continue;
    seenDirs.add(s.dirName);
    const target = s.kind === 'dir'
      ? path.join(s.source, s.dirName)
      : path.join(s.source, s.dirName + '.md');
    linkActions.push({ name: s.dirName, target, linkPath: path.join(dirs.offDir, s.dirName) });
  }

  const indexSizes = buckets.map((b) => ({
    category: b.category, skills: b.items.length,
    tokens: b.items.reduce((a, s) => a + indexEntryTokens(s), 0),
    splitBy: b.splitBy || null,
  }));

  const files = [
    { path: path.join(dirs.skillsRoot, ROUTER_NAME, 'SKILL.md'), what: 'router' },
    ...buckets.map((b) => ({ path: path.join(dirs.indexDir, `${b.category}.md`), what: 'index' })),
    { path: path.join(dirs.indexDir, `${MANAGER_NAME}.md`), what: 'manager' },
    { path: path.join(dirs.indexDir, '.dsh-skill-router.manifest.json'), what: 'manifest' },
  ];
  return { dirs, buckets, skills, invalid, linkActions, indexSizes, files, excludes, overrides };
}

function cmdPlan(o) {
  const p = buildPlan(o);
  const m = measureCatalog(p.skills);
  if (o.json) {
    process.stdout.write(JSON.stringify({
      skills: p.skills.length, skippedInvalid: p.invalid.length,
      catalogIfResident: m, categories: p.indexSizes,
      links: { create: p.linkActions.length }, files: p.files, dryRun: o.dryRun,
    }, null, 2) + '\n');
    return;
  }
  process.stdout.write(`Sources: ${p.skills.length} catalog-able skills` +
    (p.invalid.length ? ` (+${p.invalid.length} skipped: invalid frontmatter or duplicates)` : '') + `\n`);
  process.stdout.write(`If resident instead, the catalog would cost ~${fmtTokens(m.tokens)} tokens.\n\n`);
  process.stdout.write(`Categories (budget ${o.maxTokens} tokens per index)\n`);
  for (const c of p.indexSizes) {
    const flag = c.tokens > o.maxTokens ? '  <-- OVER BUDGET' : '';
    process.stdout.write(`  ${c.category.padEnd(36)} ${String(c.skills).padStart(4)} skills  ~${String(c.tokens).padStart(6)} tok${flag}\n`);
  }
  process.stdout.write(`\nLinks: ${p.linkActions.length} junctions in ${p.dirs.offDir}\n`);
  process.stdout.write(`Files: ${p.files.length} to write (router + ${p.buckets.length} indexes + manager + manifest)\n`);
  if (p.invalid.length) {
    process.stdout.write(`\nSkipped (${p.invalid.length}):\n`);
    for (const b of p.invalid.slice(0, 20)) process.stdout.write(`  ${b.name.padEnd(46)} ${b.reason}\n`);
    if (p.invalid.length > 20) process.stdout.write(`  … +${p.invalid.length - 20} more\n`);
  }
  if (o.dryRun) process.stdout.write(`\n(dry run — nothing written)\n`);
}

function cmdApply(o) {
  const p = buildPlan(o);
  const d = p.dirs;

  // 1) links (idempotent; never touches anything that is not ours to touch)
  const stats = { created: 0, exists: 0, conflict: 0 };
  if (!o.dryRun) fs.mkdirSync(d.offDir, { recursive: true });
  for (const a of p.linkActions) {
    const r = link(a.target, a.linkPath, { dryRun: o.dryRun });
    if (r === 'conflict') { stats.conflict++; process.stderr.write(`conflict (left alone): ${a.linkPath}\n`); }
    else stats[r === 'created' ? 'created' : 'exists']++;
  }

  // 2) router + indexes (+ manager + manifest)
  const rt = routerText({
    buckets: p.buckets, indexDir: d.indexDir, skillsRoot: d.skillsRoot,
    offDir: d.offDir, total: p.skills.length, locale: o.locale,
  }) + `\n<!-- ${MARKER} -->\n`;
  const written = [];
  if (!o.dryRun) {
    if (writeIfChanged(path.join(d.skillsRoot, ROUTER_NAME, 'SKILL.md'), rt)) written.push('router');
    for (const b of p.buckets) {
      const t = indexText(b, { locale: o.locale }) + `<!-- ${MARKER} -->\n`;
      if (writeIfChanged(path.join(d.indexDir, `${b.category}.md`), t)) written.push(b.category);
    }
    const mt = managerText({
      indexDir: d.indexDir, skillsRoot: d.skillsRoot, offDir: d.offDir,
      cli: 'npx dsh-skill-router', locale: o.locale,
    }) + `\n<!-- ${MARKER} -->\n`;
    if (writeIfChanged(path.join(d.indexDir, `${MANAGER_NAME}.md`), mt)) written.push(MANAGER_NAME);

    const manifest = {
      tool: 'dsh-skill-router', version: VERSION, marker: MARKER,
      generatedAt: new Date().toISOString(),
      sources: p.skills.length ? [...new Set(p.skills.map((s) => s.source))] : [],
      skillsRoot: d.skillsRoot, offDir: d.offDir, indexDir: d.indexDir,
      files: [
        path.join(d.skillsRoot, ROUTER_NAME, 'SKILL.md'),
        ...p.buckets.map((b) => path.join(d.indexDir, `${b.category}.md`)),
        path.join(d.indexDir, `${MANAGER_NAME}.md`),
      ],
      linked: p.linkActions.length,
    };
    fs.writeFileSync(path.join(d.indexDir, '.dsh-skill-router.manifest.json'),
      JSON.stringify(manifest, null, 2), 'utf8');
  }

  if (o.json) {
    process.stdout.write(JSON.stringify({ dryRun: o.dryRun, links: stats, written }, null, 2) + '\n');
    return;
  }
  process.stdout.write(`links  : created=${stats.created} already=${stats.exists} conflict=${stats.conflict}${o.dryRun ? ' (dry run)' : ''}\n`);
  process.stdout.write(`written: ${o.dryRun ? '(dry run)' : written.length ? written.join(', ') : 'no changes'}\n`);
  if (!o.dryRun) {
    process.stdout.write(`\nThe catalog now holds a single skill (${ROUTER_NAME}). `);
    process.stdout.write(`DSH watches the roots, so it picks this up on the next model step; restart to be safe.\n`);
    process.stdout.write(`Next: dsh-skill-router verify\n`);
  }
}

// ────────────────────────────── verify ──────────────────────────────
function cmdVerify(o) {
  const d = resolveDirs(o);
  const res = verifyIndexes({ indexDir: d.indexDir, skillsRoot: d.skillsRoot, offDir: d.offDir });
  if (o.json) { process.stdout.write(JSON.stringify(res, null, 2) + '\n'); }
  else {
    process.stdout.write(`index files checked : ${res.indexFiles}\n`);
    process.stdout.write(`paths checked       : ${res.checked}\n`);
    process.stdout.write(`dead paths          : ${res.dead.length}\n`);
    for (const x of res.dead.slice(0, 20)) process.stdout.write(`  DEAD  ${x.index}  ${x.path}\n`);
    if (res.dead.length > 20) process.stdout.write(`  … +${res.dead.length - 20} more\n`);
    if (res.extraneous.length) {
      process.stdout.write(`non-router entries in the skills root (${res.extraneous.length}):\n`);
      for (const x of res.extraneous.slice(0, 10)) process.stdout.write(`  ${x}\n`);
      process.stdout.write(`  these re-inflate the catalog; move them out or re-run apply.\n`);
    }
    if (!res.manifest) process.stdout.write(`note: no manifest found (${path.join(d.indexDir, '.dsh-skill-router.manifest.json')}); restore will be limited.\n`);
  }
  process.exitCode = res.dead.length ? 1 : 0;
}

// ────────────────────────────── restore ──────────────────────────────
function cmdRestore(o) {
  const d = resolveDirs(o);
  const manifestPath = path.join(d.indexDir, '.dsh-skill-router.manifest.json');
  let manifest = null;
  try { manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')); } catch { /* best effort */ }
  const sources = manifest?.sources ?? [];
  const norm = (s) => path.resolve(s).replace(/[\\/]+$/, '').toLowerCase();

  let linksRemoved = 0; let linksKept = 0;
  if (fs.existsSync(d.offDir)) {
    for (const e of fs.readdirSync(d.offDir, { withFileTypes: true })) {
      const p = path.join(d.offDir, e.name);
      if (linkType(p) !== 'link') { linksKept++; continue; }        // never touch real dirs
      let target = null;
      try { target = fs.realpathSync(p); } catch { /* dangling */ }
      const ours = !sources.length || (target && sources.some((s) => norm(target).startsWith(norm(s))));
      if (!ours) { linksKept++; continue; }
      const r = unlink(p, { dryRun: o.dryRun });
      if (r === 'removed') linksRemoved++;
    }
  }

  let filesRemoved = 0;
  const genFiles = manifest?.files ?? [];
  if (!o.dryRun) {
    for (const f of genFiles) {
      try {
        const content = fs.readFileSync(f, 'utf8');
        if (!content.includes('dsh-skill-router')) continue;         // only our own files
        fs.rmSync(f, { force: true }); filesRemoved++;
      } catch { /* absent */ }
    }
    try {
      const routerDir = path.join(d.skillsRoot, ROUTER_NAME);
      if (fs.existsSync(routerDir)) {
        const entries = fs.readdirSync(routerDir);
        if (entries.length <= 1) fs.rmSync(routerDir, { recursive: true, force: true });
        else fs.rmSync(path.join(routerDir, 'SKILL.md'), { force: true });
        filesRemoved++;
      }
    } catch { /* absent */ }
    if (manifest) fs.rmSync(manifestPath, { force: true });
  }

  if (o.json) { process.stdout.write(JSON.stringify({ dryRun: o.dryRun, linksRemoved, linksKept, filesRemoved }, null, 2) + '\n'); return; }
  process.stdout.write(`links removed : ${linksRemoved}${o.dryRun ? ' (dry run)' : ''}   kept (not ours): ${linksKept}\n`);
  process.stdout.write(`files removed : ${filesRemoved}${o.dryRun ? ' (dry run)' : ''}\n`);
  process.stdout.write(`source libraries were never touched.\n`);
}

// ────────────────────────────── route ──────────────────────────────
function readRoutingFile(o) {
  const dirs = resolveDirs(o);
  const file = o.routing ?? path.join(dirs.dshHome, 'capabilities', 'routing.json');
  if (!fs.existsSync(file)) {
    process.stderr.write(`routing file not found: ${file}\n`);
    process.stderr.write('hint: pass --routing <path>; the file is yours to write (schema: docs/ROUTING.md)\n');
    process.exit(1);
  }
  try {
    return { file, routing: JSON.parse(fs.readFileSync(file, 'utf8')) };
  } catch (e) {
    process.stderr.write(`routing file is not valid JSON: ${file}\n  ${e.message}\n`);
    process.exit(1);
  }
}

/** 解析一组 hub 名 → 磁盘路径。三处布局（拍平 / _hubs / 原样）依次尝试。 */
function lookupHubs(routing, names, roots) {
  return names.map((name) => {
    const rec = routing?.hubs?.[name];
    if (!rec) return { name, defined: false, declaredPath: null, resolvedPath: null, layout: null, why: 'not defined in routing.hubs' };
    const hit = roots.length ? resolveHubPath(rec.path, roots) : null;
    return {
      name,
      defined: true,
      declaredPath: rec.path,
      resolvedPath: hit?.path ?? null,
      layout: hit?.layout ?? null,
      why: hit ? null : (roots.length ? 'no layout matched under the given roots' : 'no --source / --hub-root given, cannot resolve'),
    };
  });
}

function cmdRoute(o) {
  const { file, routing } = readRoutingFile(o);
  const report = validateRouting(routing);

  if (o.validate) {
    const payload = { routingFile: file, ok: report.errors.length === 0, ...report };
    if (o.json) {
      process.stdout.write(JSON.stringify(payload, null, 2) + '\n');
    } else {
      process.stdout.write(`routing file : ${file}\n`);
      process.stdout.write(`rules / hubs : ${report.ruleCount} / ${report.hubCount}\n`);
      for (const e of report.errors) process.stdout.write(`  ERROR   ${e}\n`);
      for (const w of report.warnings) process.stdout.write(`  warn    ${w}\n`);
      process.stdout.write(report.errors.length ? 'INVALID\n' : 'valid\n');
    }
    process.exit(report.errors.length ? 1 : 0);
  }

  const query = o.rest.join(' ').trim();
  if (!query) {
    process.stderr.write('missing task text: dsh-skill-router route "how do I X"\n');
    process.exit(1);
  }

  const dirs = resolveDirs(o);
  const roots = [...o.sources, ...o.hubRoots];
  const result = routeQuery(query, routing);
  const primary = result.primary;
  const indexes = (primary?.categories ?? []).map((c) => {
    const f = path.join(dirs.indexDir, `${c}.md`);
    return { category: c, file: f, exists: fs.existsSync(f) };
  });
  const hubs = lookupHubs(routing, primary?.hubs ?? [], roots);

  if (o.json) {
    process.stdout.write(JSON.stringify({
      routingFile: file, ...result, indexes, hubs,
    }, null, 2) + '\n');
    return;
  }

  const ordered = orderedRules(routing);
  process.stdout.write(`query    : ${query}\n`);
  process.stdout.write(`routing  : ${file}  (${report.ruleCount} rules, ${report.hubCount} hubs)\n`);
  for (const e of report.errors) process.stdout.write(`  ERROR in routing file: ${e}\n`);
  if (!primary) {
    process.stdout.write(`PRIMARY  : (no rule matched)\n`);
    process.stdout.write(`next     : read ${path.join(dirs.indexDir, 'other.md')} if it exists, or fall back to the router skill\n`);
    return;
  }
  process.stdout.write(`PRIMARY  : ${primary.id}  ${primary.label}\n`);
  for (const ix of indexes) {
    process.stdout.write(`  read   : ${ix.file}${ix.exists ? '' : '   (missing — run: apply)'}\n`);
  }
  if (!hubs.length) {
    process.stdout.write('  hub    : —\n');
  }
  for (const h of hubs) {
    if (h.resolvedPath) process.stdout.write(`  hub    : ${h.name} -> ${h.resolvedPath}  [${h.layout} layout]\n`);
    else process.stdout.write(`  hub    : ${h.name} (unresolved: ${h.why})\n`);
  }
  const others = result.matches.slice(1, 4);
  if (others.length) {
    process.stdout.write(`then     : ${others.map((m) => `${m.id} ${m.label}`).join(' | ')}\n`);
  }
  process.stdout.write(`(considered ${ordered.length} rules; ${result.matches.length} matched)\n`);
}

// ────────────────────────────── main ──────────────────────────────
const o = parseArgs(process.argv.slice(2));
switch (o.command) {
  case 'scan': cmdScan(o); break;
  case 'plan': cmdPlan(o); break;
  case 'apply': cmdApply(o); break;
  case 'verify': cmdVerify(o); break;
  case 'restore': cmdRestore(o); break;
  case 'route': cmdRoute(o); break;
}
